export type ReviewConnectionStatus = typeof ReviewConnectionStatus[keyof typeof ReviewConnectionStatus];


export const ReviewConnectionStatus = {
  DISCONNECTED: 'DISCONNECTED',
  PENDING: 'PENDING',
  CONNECTED: 'CONNECTED',
  ERROR: 'ERROR',
} as const;

export type ReviewResponseStatus = typeof ReviewResponseStatus[keyof typeof ReviewResponseStatus];


export const ReviewResponseStatus = {
  PENDING: 'PENDING',
  DRAFT: 'DRAFT',
  PUBLISHED: 'PUBLISHED',
} as const;

export type ReviewProviderConnectionProvider = typeof ReviewProviderConnectionProvider[keyof typeof ReviewProviderConnectionProvider];


export const ReviewProviderConnectionProvider = {
  BNDLE: 'BNDLE',
} as const;

export interface ReviewProviderConnection {
  status: ReviewConnectionStatus;
  provider: ReviewProviderConnectionProvider;
  /** @nullable */
  lastSyncedAt: string | null;
  /** @nullable */
  lastError: string | null;
  /**
     * Provider's remaining monthly Google review import capacity for this account, as of the last successful sync. Null until a sync reports it.
     * @nullable
     */
  remainingImportCapacity: number | null;
}

export interface ReviewLocation {
  id: string;
  name: string;
  /** @nullable */
  address: string | null;
  /** @nullable */
  category: string | null;
  /** @nullable */
  websiteUrl: string | null;
  isSelected: boolean;
}

export interface ReviewInboxSummary {
  totalReviews: number;
  needsReply: number;
  replied: number;
}

export interface ReviewDashboardResult {
  connection: ReviewProviderConnection;
  locations: ReviewLocation[];
  summary: ReviewInboxSummary;
}

/**
 * NOT_CONNECTED: the Google OAuth step hasn't completed yet (or was cancelled/failed) — no business account is attached. NEEDS_LOCATION: Google access is granted; pick one of `locations` to finish connecting. NO_LOCATIONS_FOUND: Google access is granted but no eligible business locations were found on that account. READY: a location is already selected and syncing is starting.
 */
export type ReviewProviderLocationStage = typeof ReviewProviderLocationStage[keyof typeof ReviewProviderLocationStage];


export const ReviewProviderLocationStage = {
  NOT_CONNECTED: 'NOT_CONNECTED',
  NEEDS_LOCATION: 'NEEDS_LOCATION',
  NO_LOCATIONS_FOUND: 'NO_LOCATIONS_FOUND',
  READY: 'READY',
} as const;

export interface ReviewProviderLocationOption {
  id: string;
  name: string;
  /** @nullable */
  address: string | null;
}

/**
 * `authUrl` is set when a fresh Google OAuth round trip is needed — open it in a new tab. It is null when bundle.social already has a Google Business account connected for this organization's team (e.g. a previous attempt got interrupted before a location was picked); in that case `stage`/`locations` describe what to do next, exactly like the connection-locations endpoint, and no new tab is needed.
 */
export interface ReviewProviderConnectionStartResult {
  connection: ReviewProviderConnection;
  /** @nullable */
  authUrl: string | null;
  stage: ReviewProviderLocationStage;
  locations: ReviewProviderLocationOption[];
}

export interface ReviewProviderConnectionInput {
  /** Business workspace to return to after Google authorization */
  businessId?: string;
}

export interface ReviewProviderLocationsResult {
  stage: ReviewProviderLocationStage;
  locations: ReviewProviderLocationOption[];
}

export interface SelectReviewProviderLocationRequest {
  locationId: string;
}

